import {elasticAllocation,gpuPlacement} from './gpu-allocation.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function elasticFields(){return `<details><summary>弹性卡数（可选）</summary><label><input name="elastic" type="checkbox">按最多可用合法卡数启动；上方卡数为最大值</label><div class="train-grid"><label>最低卡数<input name="min-cards" type="number" min="1" value="1"></label><label>Global batch<input name="global-batch" type="number" min="1" placeholder="例如 256"></label><label>每卡 micro batch<input name="micro-batch" type="number" min="1" placeholder="例如 8"></label></div><label><input name="auto-expand" type="checkbox">空卡释放后，保存并恢复到更大的合法卡数</label><p class="muted" id="elastic-note">自动扩卡需选独立调度、保存让位、自动恢复，并确认训练已接入 checkpoint 和弹性 batch 适配器。训练按实际卡数启动 DDP 并计算梯度累积；global batch 和 LR 保持不变。</p></details>`;}
export function elasticFromForm(form,cards,scheduling){return form.get('elastic')?elasticAllocation({minCards:Number(form.get('min-cards')),globalBatch:Number(form.get('global-batch')),microBatch:Number(form.get('micro-batch')),autoExpand:form.get('auto-expand')==='on'},cards,scheduling).elastic:null;}
export function allocationSummary(job){return job.elastic?`<small>弹性 ${esc(job.elastic.minCards)}–${esc(job.cards)} 张 · 当前 ${esc(job.actualCards??job.assignedIndices?.length??0)} 张</small><small>合法卡数 ${esc((job.allowedGpuCounts||[]).join(','))}${job.elastic.autoExpand?' · 保存后自动扩卡':''}</small>`:`<small>${esc(job.cards)} 张${job.assignedIndices?.length?' · GPU '+esc(job.assignedIndices.join(',')):''}</small>`;}

export function placementFields(){return `<details><summary>固定 / 共享选卡（可选）</summary><label>选卡方式<select name="gpu-placement"><option value="any">自动分配空闲显卡</option><option value="pinned">固定指定显卡</option><option value="shared">共享指定一张显卡</option></select></label><label>服务器上的物理显卡编号<input name="gpu-indices" placeholder="例如 3 或 0,2" spellcheck="false"></label><label>预计占用显存 / MiB<input name="vram-mib" type="number" min="1" placeholder="例如 4096"></label><label><input name="hami" type="checkbox">启用本机已验证的 HAMi 显存限制</label><label>HAMi SM 百分比<input name="sm-percent" type="number" min="1" max="100" value="100"></label><p id="placement-note" class="muted">先在资源页观察逐卡显存和进程，再选择挤在哪张卡上。共享只需提交者主动同意，支持同卡外部任务；显存预算用于排队准入，普通共享没有硬隔离。</p></details>`;}
export function placementFromForm(form,cards,elastic,scheduling,priority){
  const mode=form.get('gpu-placement');if(!mode||mode==='any')return null;
  return gpuPlacement({gpuIndices:String(form.get('gpu-indices')||'').split(',').map(n=>/^\d+$/.test(n.trim())?Number(n.trim()):NaN),shared:mode==='shared',...(mode==='shared'?{vramMiB:Number(form.get('vram-mib')),hami:form.get('hami')==='on',...(form.get('hami')==='on'?{smPercent:Number(form.get('sm-percent'))}:{})}:{})},cards,elastic,scheduling,priority);
}
export function placementSummary(job){const p=job.placement;return p?`<small>${p.shared?'共享':'固定'} GPU ${esc(p.gpuIndices.join(','))}${p.shared?' · 预算 '+esc(p.vramMiB)+' MiB':''}${p.hami?' · HAMi SM '+esc(p.smPercent)+'%':''}</small>`:'';}
